/**
 * 창 전체 키 처리 규칙(순수 함수). 캔버스에 초점이 있으면 뷰어가 F·1~7·Esc(측정 지우기)를 직접 받고
 * 전파를 멈추므로, 여기에는 뷰어가 받지 않은 키만 온다(app 쪽에서 창의 bubble 단계로 듣는다).
 * F·1~7 같은 뷰어 키의 뜻은 앱이 따로 들지 않고 `Viewer3d.handleKey`에 넘겨 코어 규칙을 그대로 쓴다.
 */
import type { ViewName } from 'opencad-viewer3d/viewkeys';

/**
 * 표준 뷰 메뉴 순서. 숫자 키 표(VIEW_KEYS)·뷰 이름(VIEW_LABELS — 화면 언어 번역은 i18n.ts가 이 표를 고친다)·키 글(viewKeyOf)은
 * 66차부터 코어 0.54.0 작은 모듈 `opencad-viewer3d/viewkeys`(아무것도 가져오지 않는다)에서 바로 가져온다 —
 * 63~65차는 코어 camera 모듈이 첫 화면 JS에 통째로 오지 않게 같은 표를 여기에 복제해 두었다(tests/app/core-split.test.ts)
 */
export const VIEW_MENU: ViewName[] = ['front', 'back', 'left', 'right', 'top', 'bottom', 'seIso', 'swIso', 'neIso', 'nwIso'];

/**
 * 할 일:
 * - open: 열기 상자(Ctrl/⌘+O)
 * - escape: 앱 쪽 Esc 순서(메뉴 닫기 → 해석 취소 → 측정 지우기·끄기 → 고르기 풀기)
 * - grid: 격자(F7, 코어는 받지 않는 키)
 * - hide: 고른 것 숨기기(H), isolate: 고른 것만 보기·격리 풀기(I), home: 홈 뷰(Home)
 * - viewer: 뷰어 키일 수 있으니 `viewer.handleKey`에 넘긴다(F·1~7 등, 처리 여부는 코어가 정한다)
 * - undo: 분해 손질 한 단계 되돌리기(Ctrl/⌘+Z — 되돌릴 것이 없으면 앱이 아무것도 하지 않는다)
 * - redo: 되돌린 분해 손질 다시 하기(Ctrl/⌘+Shift+Z, Windows 꼴 Ctrl+Y — ⌘+Y는 브라우저 방문 기록이라 받지 않는다. 다시 할 것이 없으면 아무것도 하지 않는다)
 */
export type KeyAction = 'open' | 'grid' | 'escape' | 'hide' | 'isolate' | 'home' | 'viewer' | 'undo' | 'redo';

export interface KeyInput {
  key: string;
  ctrl?: boolean;
  meta?: boolean;
  alt?: boolean;
  shift?: boolean;
  /** 글 입력 칸(input·textarea·select·contentEditable)에서 눌렀는지 */
  inText?: boolean;
  /** 초점이 있는 조작 칸(controlOf): 밀대·탭 본문(153차)은 Home·End·Page·화살표, 라디오는 화살표, 메뉴 항목(158차)은 Ctrl·⌘·Alt 없는 키 모두를 스스로 쓴다 */
  control?: Control | null;
  /** 열린 문서가 있는지 */
  hasDoc?: boolean;
  /** 모달 대화 상자가 열려 있는지(154차 — dialog.ts dialogOpen) */
  modal?: boolean;
  /** 172차: 앱 설정에서 「3D 보기 밖에서도 한 글자 단축키」를 끄고 초점이 3D 보기 밖인지(그러면 한 글자 키는 받지 않는다) */
  viewOnly?: boolean;
}

/** 눌린 키 → 할 일(없으면 null) */
export function routeKey(k: KeyInput): KeyAction | null {
  if (k.inText) return null;
  // 154차: 모달 대화 상자가 열린 동안 나머지 문서는 쓸 수 없다(HTML 모달의 inert·WAI-ARIA APG Dialog) — 뒤의 3D 보기·문서를 바꾸는 앱 글쇠도 모두 받지 않고,
  // Esc만 그대로(Esc 차례의 첫 칸이 대화 상자 닫기). 대화 상자 안 칸의 Tab·Enter·Space·화살표는 브라우저 기본 동작 그대로
  if (k.modal && k.key !== 'Escape') return null;
  if ((k.control === 'range' || k.control === 'scroll') && RANGE_KEYS.has(k.key)) return null;
  if (k.control === 'radio' && ARROW_KEYS.has(k.key)) return null;
  const mod = !!(k.ctrl || k.meta);
  if (mod && !k.alt && (k.key === 'o' || k.key === 'O')) return 'open';
  if (mod && !k.alt && k.hasDoc && (k.key === 'z' || k.key === 'Z')) return k.shift ? 'redo' : 'undo';
  if (k.ctrl && !k.meta && !k.alt && !k.shift && k.hasDoc && (k.key === 'y' || k.key === 'Y')) return 'redo';
  if (mod || k.alt) return null;
  // 172차(WCAG 2.1.4 문자 키 단축키): 끈 사용자에게 수식 글쇠 없는 한 글자 키(H·I·F·1~7 — Shift만 붙은 것도)는 3D 보기에 초점이 있을 때만(음성 입력이 친 글자가
  // 숨기기·격리·보기 바꿈으로 돌지 않게). Esc·F7·Home·화살표·Shift는 글자 키가 아니라 그대로
  if (k.viewOnly && k.key.length === 1) return null;
  if (k.key === 'Escape') return 'escape';
  // 158차: 초점이 열린 메뉴의 항목이면 나머지 키는 메뉴 것(WAI-ARIA APG Menu — 닫기 전까지 그 메뉴의 키, 글자는 그 메뉴 안 항목 찾기 몫).
  // 전에는 메뉴를 연 채 H·I·F·1~7·F7이 뒤의 고르기·3D 보기·격자를 바꿔 메뉴의 항목 글·켜짐 표시가 어긋났다. 수식 글쇠 명령·Esc는 위 차례 그대로
  if (k.control === 'menu') return null;
  if (!k.hasDoc) return null;
  if (k.key === 'F7') return 'grid';
  if (k.key === 'h' || k.key === 'H') return 'hide';
  if (k.key === 'i' || k.key === 'I') return 'isolate';
  if (k.key === 'Home') return 'home';
  return 'viewer';
}

type Store = Pick<Storage, 'getItem' | 'setItem'> | null;
const LETTER_KEYS = 'opencad-step-letter-keys';

/** 172차: 한 글자 단축키를 3D 보기 밖에서도 받는지(앱 설정 메뉴 — 기본 켬, 끄면 이 브라우저에 'view'를 기억). 없거나 못 읽으면 켬 */
export function readLetterKeys(s: Store): boolean {
  try {
    return s?.getItem(LETTER_KEYS) !== 'view';
  } catch {
    return true;
  }
}

/** 그 설정을 기억하고(못 쓰면 이 창 동안만) 그 값을 돌려준다 */
export function writeLetterKeys(s: Store, on: boolean): boolean {
  try {
    s?.setItem(LETTER_KEYS, on ? 'any' : 'view');
  } catch {
    /* 저장소를 못 쓰는 환경 */
  }
  return on;
}

/**
 * 220차(WAI-ARIA 1.2 §6.7 — 값은 그 요소의 일을 실제로 하는 키만): 3D 보기 밖 버튼·메뉴 항목의 aria-keyshortcuts 값. 172차 설정을 끄면(letters false)
 * 수식 글쇠 없는 한 글자 키(F·H·I·1~7 — Shift만 붙은 것도, routeKey viewOnly와 같은 가름)는 3D 보기에 초점이 있을 때만 들으므로 뺀다. 남는 키가 없으면 null
 */
export function outsideKeys(keys: string, letters: boolean): string | null {
  return (letters ? keys : keys.split(' ').filter((k) => !/^(Shift\+)?.$/.test(k)).join(' ')) || null;
}

/**
 * 3D 보기 밖 버튼에 outsideKeys 값을 단다(없으면 뗀다 — 172차 설정을 바꾸면 다시 부른다).
 * 221차: name(키가 한 글자 하나인 버튼)을 주면 말풍선도 값을 따라 「name (키)」, 값이 없으면 name만(WAI-ARIA 1.2 §6.7 — 말풍선은 그 요소의 단축키를 드러내는 자리.
 * 끈 동안 그 버튼에서 듣지 않는 F·I를 말하지 않는다 — 키는 그 키가 듣는 3D 보기의 값·설정 항목 이름에 그대로)
 */
export function markKeys(el: Element, keys: string, letters: boolean, name?: string): void {
  const v = outsideKeys(keys, letters);
  if (v) el.setAttribute('aria-keyshortcuts', v);
  else el.removeAttribute('aria-keyshortcuts');
  if (name) el.setAttribute('title', v ? `${name} (${v})` : name);
}

/**
 * 3D 보기(캔버스)가 받은 화살표의 임자(62차 — 코어 0.46.0 가상 커서와 두 점 측정 방향 잠금이 나눠 쓴다): 'core' = 코어(가상 커서 켜기·옮기기), 'lock' = 앱 방향 잠금.
 * 가상 커서가 켜져 있으면 코어, 꺼져 있고 마우스·펜이 3D 보기 위에 있으면 앱(마우스로 첫 점을 찍고 화살표로 잠그던 흐름 그대로), 아니면 코어
 */
export function arrowOwner(cursorOn: boolean, pointerIn: boolean): 'core' | 'lock' {
  return !cursorOn && pointerIn ? 'lock' : 'core';
}

/** 키보드로 값을 바꾸는 조작 칸(scroll: 초점을 받은 탭 본문 — 굴리는 키를 스스로 쓴다, 153차; menu: 열린 메뉴의 항목, 158차) */
export type Control = 'range' | 'radio' | 'scroll' | 'menu';

const ARROW_KEYS = new Set(['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']);
const RANGE_KEYS = new Set([...ARROW_KEYS, 'Home', 'End', 'PageUp', 'PageDown']);

/**
 * 이벤트 대상이 밀대(range)·라디오면 그 종류(그 칸이 쓰는 키는 뷰어·홈 뷰로 보내지 않는다).
 * 153차: 탭 본문(role=tabpanel — 속성·정보 탭은 본문 자체가 Tab 멈춤인 스크롤 영역) 자체면 'scroll' — Home만 홈 뷰로 가고 본문은 맨 위로 가지 않았다.
 * 158차: 메뉴 항목(role=menuitem·menuitemradio·menuitemcheckbox — menu.ts)이면 'menu'
 */
export function controlOf(t: EventTarget | null): Control | null {
  if (!t) return null;
  const role = (t as HTMLElement).getAttribute?.('role');
  if (role === 'tabpanel') return 'scroll';
  if (role?.startsWith('menuitem')) return 'menu';
  if ((t as HTMLElement).tagName !== 'INPUT') return null;
  const type = ((t as HTMLInputElement).type || '').toLowerCase();
  return type === 'range' || type === 'radio' ? type : null;
}

/** 이벤트 대상이 글 입력 칸인지 */
export function isTextTarget(t: EventTarget | null): boolean {
  if (!t || typeof (t as HTMLElement).tagName !== 'string') return false;
  const el = t as HTMLElement;
  const tag = el.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    const type = ((el as HTMLInputElement).type || 'text').toLowerCase();
    return !['checkbox', 'radio', 'button', 'submit', 'reset', 'range', 'color', 'file'].includes(type);
  }
  return !!el.isContentEditable;
}
